{
  "root": "main_stack",
  "state": {
    "trafficData": [
      {
        "source": "Organic Search",
        "visits": 5000,
        "proportion": "41.67%"
      },
      {
        "source": "Social Media",
        "visits": 3500,
        "proportion": "29.17%"
      },
      {
        "source": "Direct",
        "visits": 2000,
        "proportion": "16.67%"
      },
      {
        "source": "Referral",
        "visits": 1500,
        "proportion": "12.50%"
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_h2",
        "intro_text",
        "traffic_section_h2",
        "summary_text",
        "traffic_table",
        "chart_proposal_text"
      ]
    },
    "title_h2": {
      "type": "Text",
      "props": {
        "text": "Website Traffic Overview",
        "variant": "h2"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "This analysis breaks down your website's traffic by source, highlighting the contribution of each channel and identifying your primary traffic driver.",
        "variant": "body"
      },
      "children": []
    },
    "traffic_section_h2": {
      "type": "Text",
      "props": {
        "text": "Traffic Source Proportions & Chart Proposal",
        "variant": "h2"
      },
      "children": []
    },
    "summary_text": {
      "type": "Text",
      "props": {
        "text": "Your website received a total of 12,000 visits from the provided sources. Organic Search is currently your primary traffic driver.",
        "variant": "body"
      },
      "children": []
    },
    "traffic_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "source",
            "label": "Source"
          },
          {
            "key": "visits",
            "label": "Visits"
          },
          {
            "key": "proportion",
            "label": "Proportion"
          }
        ],
        "statePath": "/trafficData",
        "domain": "generic",
        "preferredPresentation": "cards",
        "primaryColumn": "source",
        "highlightColumns": [
          "visits",
          "proportion"
        ]
      },
      "children": []
    },
    "chart_proposal_text": {
      "type": "Text",
      "props": {
        "text": "To visually represent this data and highlight the primary driver, a Pie Chart would be highly effective. It would show segments for each traffic source (Organic Search, Social Media, Direct, Referral) with their corresponding percentage values. The \"Organic Search\" segment should be visually emphasized to clearly show it as the largest proportion.",
        "variant": "body"
      },
      "children": []
    }
  }
}
